import fs from 'node:fs';
import path from 'node:path';
import process from 'node:process';
import { chromium } from 'playwright';

const FRONTEND='https://casepath-swiss-claim-lab.onrender.com';
const API='https://casepath-agentic-api.onrender.com';
const RELEASE='12.0.2';
const FLAGSHIP='BS-DEF-2026-041';
const LATER='BS-DEF-2026-057';
const OUT=path.resolve('casepath/reports/public-v12.0.2');
fs.mkdirSync(OUT,{recursive:true});
const result={release:RELEASE,started_at:new Date().toISOString(),checks:[],errors:[],screenshots:[]};
const sleep=ms=>new Promise(r=>setTimeout(r,ms));
function check(name,condition,detail=''){result.checks.push({name,passed:Boolean(condition),detail});if(!condition)throw new Error(`${name}: ${detail}`)}
async function response(url,options={},timeout=45000){const c=new AbortController();const t=setTimeout(()=>c.abort(),timeout);try{return await fetch(url,{cache:'no-store',...options,signal:c.signal})}finally{clearTimeout(t)}}
async function json(url,options={}){const r=await response(url,options);const text=await r.text();if(!r.ok)throw new Error(`${url} -> ${r.status}: ${text.slice(0,240)}`);return JSON.parse(text)}
async function waitRelease(){let last;const end=Date.now()+18*60*1000;while(Date.now()<end){try{const [frontRes,releaseRes,health,ready,deploy,demo]=await Promise.all([response(`${FRONTEND}/?gate=${Date.now()}`),response(`${FRONTEND}/release.json?gate=${Date.now()}`),json(`${API}/healthz?gate=${Date.now()}`),json(`${API}/readyz?gate=${Date.now()}`),json(`${API}/deployment-health?gate=${Date.now()}`),json(`${API}/api/demo?gate=${Date.now()}`)]);const html=await frontRes.text();const rel=JSON.parse(await releaseRes.text());last={front:frontRes.status,release:rel,health,ready,deploy,demo_claim_id:demo.demo_claim_id};if(frontRes.ok&&releaseRes.ok&&!html.includes('Waiting for the v12.0.1 workspace')&&!html.includes("frontend/index.html")&&rel.release===RELEASE&&health.release===RELEASE&&deploy.release===RELEASE&&deploy.data_module==='data_v12'&&deploy.pipeline_module==='pipeline_v12'&&ready.claims===4&&demo.demo_claim_id===FLAGSHIP)return {demo,ready,deploy,html};}catch(e){last={error:String(e)}}await sleep(10000)}throw new Error(`release alignment timeout: ${JSON.stringify(last)}`)}
function walk(v,fn,out=[]){if(v&&typeof v==='object'){if(fn(v))out.push(v);for(const x of Object.values(v))walk(x,fn,out)}return out}
async function waitRun(id){const end=Date.now()+120000;let run;while(Date.now()<end){run=await json(`${API}/api/runs/${id}`);if(run.status==='complete')return run;if(run.status==='failed')throw new Error(JSON.stringify(run));await sleep(400)}throw new Error(`run timeout ${id}`)}
async function apiFlow(demo){const attachments=demo.claim.attachments||demo.claim.artifacts||[];check('ten source attachments',attachments.length>=10,String(attachments.length));let pdfs=0,photos=0;for(const item of attachments){const id=item.artifact_id||item.id;const media=item.media_type||item.mime_type||'';const raw=await response(`${API}/api/artifacts/${encodeURIComponent(id)}`);const bytes=new Uint8Array(await raw.arrayBuffer());check(`attachment ${item.filename||id} opens`,raw.ok&&bytes.byteLength>100,`${raw.status}/${bytes.byteLength}`);if(media==='application/pdf'){pdfs++;const pages=[1,item.page_count||1];for(const page of [...new Set(pages)]){const rendered=await response(`${API}/api/artifacts/${encodeURIComponent(id)}/pages/${page}`);const b=new Uint8Array(await rendered.arrayBuffer());check(`PDF ${item.filename||id} page ${page} renders`,rendered.ok&&rendered.headers.get('content-type')?.includes('image/png')&&b.byteLength>1000,`${rendered.status}/${rendered.headers.get('content-type')}/${b.byteLength}`)}}if(media.startsWith('image/')){photos++;check(`photo ${item.filename||id} is substantive`,raw.headers.get('content-type')?.startsWith('image/')&&bytes.byteLength>15000,`${raw.headers.get('content-type')}/${bytes.byteLength}`)}}check('multiple PDFs present',pdfs>=3,String(pdfs));check('multiple photographs present',photos>=3,String(photos));
await json(`${API}/api/demo/reset`,{method:'POST'});const created=await json(`${API}/api/runs`,{method:'POST',headers:{'content-type':'application/json'},body:JSON.stringify({claim_id:FLAGSHIP})});const run=await waitRun(created.run_id);const events=run.events||run.audit||run.trace||[];check('real analysis events emitted',events.length>=7,String(events.length));check('terminal event emitted',events.some(e=>e.stage==='complete'),JSON.stringify(events.slice(-2)));const text=JSON.stringify(run.result);check('process result present',/process|question|current_blocker/i.test(text),text.slice(0,180));check('evidence result present',/checklist|evidence|document/i.test(text),text.slice(0,180));const precedentArrays=walk(run.result,v=>Array.isArray(v)&&v.length===3&&v.every(x=>x&&typeof x==='object'&&('claim_id'in x||'case_id'in x)));check('exactly three precedents',precedentArrays.length>0,String(precedentArrays.length));check('active claim excluded from precedents',!JSON.stringify(precedentArrays[0]).includes(FLAGSHIP));const before=JSON.stringify(run.result);const review=await json(`${API}/api/runs/${created.run_id}/review`,{method:'POST',headers:{'content-type':'application/json'},body:JSON.stringify({decision:'approve_with_edit',building_envelope_mode:'conditional',confidence:.94,justification:'Start with one neutral inspection. Request broader building-envelope testing only if the initial causal assessment is inconclusive.'})});const after=await json(`${API}/api/runs/${created.run_id}`);check('expert review accepted',Boolean(review));check('accepted result recomputed',before!==JSON.stringify(after.result)||JSON.stringify(review).includes('conditional'));const knowledge=await json(`${API}/api/knowledge?gate=${Date.now()}`);check('reviewed memory persisted',JSON.stringify(knowledge).includes(FLAGSHIP));const proof=await json(`${API}/api/learning-proof?gate=${Date.now()}`);const proofText=JSON.stringify(proof);check('later claim identified',proofText.includes(LATER));check('later claim uses reviewed memory',proofText.includes(FLAGSHIP));result.api={run_id:created.run_id,event_count:events.length,precedents:precedentArrays[0],review,knowledge,proof};return {run,precedents:precedentArrays[0]}}
async function browserFlow(apiResult){const browser=await chromium.launch({headless:true});try{for(const spec of [{name:'desktop',width:1440,height:900,deep:true},{name:'mobile-390',width:390,height:844,deep:false},{name:'mobile-320',width:320,height:700,deep:false}]){const context=await browser.newContext({viewport:{width:spec.width,height:spec.height}});const page=await context.newPage();const consoleErrors=[],pageErrors=[],requestFailures=[];page.on('console',m=>{if(m.type()==='error')consoleErrors.push(m.text())});page.on('pageerror',e=>pageErrors.push(String(e)));page.on('requestfailed',r=>{if(!/favicon\.ico/.test(r.url()))requestFailures.push({url:r.url(),error:r.failure()?.errorText})});await page.goto(`${FRONTEND}/?fresh=${Date.now()}-${spec.name}`,{waitUntil:'domcontentloaded',timeout:90000});await page.waitForFunction(()=>/BS-DEF-2026-041|Recurring mould|What the customer sent/i.test(document.body.innerText)&&!/Waiting for the v12\.0\.1 workspace/i.test(document.body.innerText),null,{timeout:90000});await page.waitForTimeout(700);const body=await page.locator('body').innerText();check(`${spec.name} renders direct claim`,/BS-DEF-2026-041|Recurring mould/i.test(body));check(`${spec.name} has no loader failure`,!/HTTP 404|Waiting for the v12\.0\.1 workspace/i.test(body));const dims=await page.evaluate(()=>({innerWidth,doc:document.documentElement.scrollWidth,body:document.body.scrollWidth}));check(`${spec.name} has no page overflow`,Math.max(dims.doc,dims.body)<=dims.innerWidth+1,JSON.stringify(dims));const shot=path.join(OUT,`${spec.name}-gate-loaded.png`);await page.screenshot({path:shot,fullPage:false});result.screenshots.push(shot);if(spec.deep){const controls=page.locator('#attachmentList button, #attachmentList [role="button"], .attachment-list button, .attachment-list [role="button"]');check('desktop shows ten attachment controls',(await controls.count())>=10,String(await controls.count()));const analyse=page.locator('#analyseBtn, button').filter({hasText:/Analyse claim/i}).first();check('analyse action available',(await analyse.count())===1);await analyse.click();await page.waitForFunction(()=>{const n=document.querySelector('#result,.result-section');return n&&!n.hidden&&getComputedStyle(n).display!=='none'},null,{timeout:120000});await page.locator('#result,.result-section').first().scrollIntoViewIfNeeded();await page.waitForTimeout(700);const finalBody=await page.locator('body').innerText();check('browser renders process',/handling process|current question|what caused|cause of/i.test(finalBody));check('browser renders evidence',/evidence|inspection|assessment|still needed/i.test(finalBody));for(const p of apiResult.precedents){const id=p.claim_id||p.case_id;check(`browser shows precedent ${id}`,finalBody.includes(id),id)}const finalShot=path.join(OUT,'desktop-gate-result.png');await page.screenshot({path:finalShot,fullPage:false});result.screenshots.push(finalShot);const form=page.locator('#reviewForm');if(await form.count()){const textarea=form.locator('textarea').first();if(await textarea.count())await textarea.fill('Start with one neutral inspection and make broader testing conditional on an inconclusive first assessment.');const submit=form.locator('button[type="submit"],button').filter({hasText:/Save|Approve|Submit|Apply/i}).first();check('expert review control visible',(await submit.count())===1);await submit.click();await page.waitForFunction(()=>/saved|case memory|available immediately|reviewed precedent|shared knowledge has not changed/i.test(document.body.innerText),null,{timeout:30000});check('expert review confirmation visible',/saved|case memory|available immediately|reviewed precedent/i.test(await page.locator('body').innerText()));const reviewShot=path.join(OUT,'desktop-gate-review.png');await page.screenshot({path:reviewShot,fullPage:false});result.screenshots.push(reviewShot)}}await page.waitForTimeout(300);check(`${spec.name} console errors`,consoleErrors.length===0,JSON.stringify(consoleErrors));check(`${spec.name} page errors`,pageErrors.length===0,JSON.stringify(pageErrors));check(`${spec.name} request failures`,requestFailures.length===0,JSON.stringify(requestFailures));await context.close()}}finally{await browser.close()}}
try{const deployed=await waitRelease();check('frontend and API release align',deployed.deploy.release===RELEASE&&deployed.deploy.frontend_release===RELEASE&&deployed.deploy.api_release===RELEASE);const apiResult=await apiFlow(deployed.demo);await browserFlow(apiResult);result.status='passed'}catch(error){result.status='failed';result.errors.push({message:String(error),stack:error?.stack||''})}finally{result.finished_at=new Date().toISOString();result.passed=result.checks.filter(x=>x.passed).length;result.failed=result.checks.filter(x=>!x.passed).length+(result.status==='failed'&&result.checks.every(x=>x.passed)?1:0);fs.writeFileSync(path.join(OUT,'release-gate.json'),JSON.stringify(result,null,2));fs.writeFileSync(path.join(OUT,result.status==='passed'?'RELEASE_ACCEPTED.json':'RELEASE_REJECTED.json'),JSON.stringify({status:result.status,release:RELEASE,passed:result.passed,failed:result.failed,finished_at:result.finished_at},null,2))}
if(result.status!=='passed'){console.error(JSON.stringify(result,null,2));process.exit(1)}console.log(JSON.stringify({status:result.status,passed:result.passed,failed:result.failed},null,2));
